/* Generated by Trae Work — chart + diagram bootstrap for nvbandwidth testcase guide */
(function () {
  'use strict';

  var css = getComputedStyle(document.documentElement);
  function v(name, fallback) {
    var val = css.getPropertyValue(name);
    return (val && val.trim()) || fallback;
  }

  var INK = v('--ink', '#14161a');
  var MUTED = v('--muted', '#5b6470');
  var RULE = v('--rule', '#e3e6ea');
  var ACCENT = v('--accent', '#4e7d00');
  var ACCENT2 = v('--accent2', '#1f6feb');
  var BG2 = v('--bg2', '#ffffff');
  var FONT = v('--font', 'sans-serif');
  var MONO = v('--font-mono', 'monospace');

  /* ---------------- Mermaid ---------------- */
  if (window.mermaid) {
    window.mermaid.initialize({
      startOnLoad: true,
      theme: 'base',
      securityLevel: 'loose',
      fontFamily: FONT,
      flowchart: { curve: 'basis', padding: 20, nodeSpacing: 46, rankSpacing: 58 },
      sequence: { diagramMarginX: 12, diagramMarginY: 12, actorMargin: 46, wrap: true, messageAlign: 'center' },
      themeVariables: {
        fontFamily: FONT,
        fontSize: '14px',
        primaryColor: '#f3f6ec',
        primaryTextColor: INK,
        primaryBorderColor: ACCENT,
        secondaryColor: '#eef3fd',
        secondaryTextColor: INK,
        secondaryBorderColor: ACCENT2,
        tertiaryColor: BG2,
        lineColor: '#8d97a3',
        textColor: INK,
        mainBkg: '#f3f6ec',
        nodeBorder: ACCENT,
        clusterBkg: '#fbfcfa',
        clusterBorder: RULE,
        edgeLabelBackground: BG2,
        noteBkgColor: '#f7f9f3',
        noteBorderColor: RULE,
        noteTextColor: INK,
        classFontFamily: MONO,
        classFontSize: '12px',
        classText: INK,
        labelBackground: BG2,
        actorBkg: '#f3f6ec',
        actorBorder: ACCENT,
        actorTextColor: INK,
        signalColor: '#8d97a3',
        signalTextColor: INK
      }
    });
  }

  /* ---------------- ECharts: distribution ---------------- */
  var categories = [
    'H2D 单向',
    'H2D 双向',
    'D2H 单向',
    'D2H 双向',
    '多 GPU → CPU',
    '多 GPU → CPU 双向',
    'CPU → 多 GPU',
    'CPU → 多 GPU 双向',
    'H↔D 往返延迟',
    'D2D 单向',
    'D2D 双向',
    'D2D 延迟',
    'D2D 汇聚 all_to_one',
    'D2D 分发 one_to_all',
    'GPU 本地拷贝 / 读写',
    '多节点 单向',
    '多节点 双向',
    '多节点 汇聚 / 分发',
    '多节点 广播',
    '多节点 对分',
    '多节点 Fabric 组播'
  ];

  var values = [2, 2, 2, 2, 2, 2, 2, 2, 1, 6, 6, 2, 4, 4, 5, 6, 6, 2, 2, 1, 2];
  var SINGLE_NODE_COUNT = 15;

  var dom = document.getElementById('chart-dist');
  if (dom && window.echarts) {
    var chart = window.echarts.init(dom, null, { renderer: 'svg' });

    chart.setOption({
      animation: false,
      textStyle: { fontFamily: FONT, fontSize: 12, color: INK },
      grid: { left: 168, right: 56, top: 16, bottom: 36 },
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'shadow' },
        appendToBody: true,
        backgroundColor: BG2,
        borderColor: RULE,
        textStyle: { color: INK, fontFamily: FONT, fontSize: 12 },
        formatter: function (params) {
          var p = params[0];
          var kind = p.dataIndex < SINGLE_NODE_COUNT ? '单节点' : '多节点';
          return p.name + '<br/>' + kind + ' · ' + p.value + ' 个用例';
        }
      },
      xAxis: {
        type: 'value',
        minInterval: 1,
        max: 7,
        splitLine: { lineStyle: { color: RULE, type: 'dashed' } },
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { color: MUTED, fontFamily: MONO, fontSize: 11 }
      },
      yAxis: {
        type: 'category',
        inverse: true,
        data: categories,
        axisLine: { lineStyle: { color: RULE } },
        axisTick: { show: false },
        axisLabel: {
          color: INK,
          fontFamily: FONT,
          fontSize: 11.5,
          margin: 12
        }
      },
      series: [
        {
          type: 'bar',
          barWidth: 13,
          data: values.map(function (val, i) {
            return {
              value: val,
              itemStyle: {
                color: i < SINGLE_NODE_COUNT ? ACCENT : ACCENT2,
                borderRadius: [0, 3, 3, 0]
              }
            };
          }),
          label: {
            show: true,
            position: 'right',
            distance: 7,
            color: MUTED,
            fontFamily: MONO,
            fontSize: 11,
            fontWeight: 'bold'
          }
        }
      ]
    });

    var resizeTimer = null;
    window.addEventListener('resize', function () {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function () { chart.resize(); }, 120);
    });
  }
})();
